+
+function refreshUI() {
+  speedBtns.forEach((b) => b.classList.toggle('on', parseFloat(b.dataset.v) === state.speed));
+  viewBtns.forEach((b) => b.classList.toggle('on', b.dataset.v === state.view));
+  playBtn.textContent = state.playing ? 'Pause' : 'Play';
+  $('setBtn').classList.toggle('on', !panel.classList.contains('closed'));
+}
+function togglePause() { state.playing = !state.playing; refreshUI(); }
+function applyNow() {
+  state.settings = readSettings();
+  state.playing = true;
+  startRun(state.settings);
+  refreshUI();
+}
+function setPanel(open) { panel.classList.toggle('closed', !open); refreshUI(); }
+
+playBtn.addEventListener('click', () => { togglePause(); playBtn.blur(); });
+$('replayBtn').addEventListener('click', () => { applyNow(); $('replayBtn').blur(); });
+$('applyBtn').addEventListener('click', () => { applyNow(); $('applyBtn').blur(); });
+$('defBtn').addEventListener('click', () => { for (const f of SCHEMA) inputs[f.k].value = String(f.def); $('defBtn').blur(); });
+$('setBtn').addEventListener('click', () => { setPanel(panel.classList.contains('closed')); $('setBtn').blur(); });
+$('closeBtn').addEventListener('click', () => setPanel(false));
+
+window.addEventListener('keydown', (e) => {
+  const el = document.activeElement;
+  const typing = el && el.tagName === 'INPUT';
+  if (e.code === 'Escape') { setPanel(false); return; }
+  if (typing) return;
+  if (e.code === 'Space') {
+    e.preventDefault(); togglePause();
+    if (el && el.tagName === 'BUTTON') el.blur();
+    return;
+  }
+  if (e.code === 'KeyR') { applyNow(); return; }
+  const vi = ['Digit1', 'Digit2', 'Digit3', 'Digit4'].indexOf(e.code);
+  if (vi >= 0) { state.view = VIEWS[vi][0]; camS.snap = true; refreshUI(); }
+});
+
+function resize() {
+  const w = window.innerWidth, h = window.innerHeight;
+  renderer.setSize(w, h, false);
+  camera.aspect = w / h; camera.updateProjectionMatrix();
