+function updateHud(r) {
+  if (!r) return;
+  let moved = 0; for (const b of r.bricks) if (b.moved) moved++;
+  const phase = r.settled ? 'settled' : r.impactT !== null ? 'impact' : 'approach';
+  hudEl.textContent = `t ${r.simTime.toFixed(2)}s  ${r.speed.toFixed(1)} m/s  broken ${r.broken}/${r.joints.length}  bricks ${moved}/${r.bricks.length}  ${phase}`;
+}
+
+/* ============================================================================
+   Run lifecycle + main loop
+============================================================================ */
+function disposeRun(r) {
+  if (!r) return;
+  scene.remove(r.group);
