+  dustPS.clear(); sparkPS.clear(); skidN = 0; skidMesh.count = 0; skidMesh.instanceMatrix.needsUpdate = true;
+  const r = createRun({ ...s });
+  scene.add(r.group);
+  run = r;
+  camS.snap = true; orb.userDist = null;
+  syncVisuals(r, 0);
+  updateBounds(r);
+  updateHud(r);
+}
+
+let lastT = performance.now();
+function frame(now) {
+  requestAnimationFrame(frame);
+  const dt = Math.min(0.05, (now - lastT) / 1000); lastT = now;
+  if (run) {
+    let simDt = 0;
+    if (state.playing) {
+      run.acc += dt * state.speed;
