+      if (run.acc > DT) run.acc = DT * 0.5;
+      simDt = n * DT;
+    }
+    syncVisuals(run, simDt);
+    updateEffects(run, simDt);
+    updateCamera(run, dt, now / 1000);
+    updateSun(run);
+    if (now - run.lastHud > 120) { updateHud(run); run.lastHud = now; }
+  }
+  sky.position.copy(camera.position);
+  renderer.render(scene, camera);
+}
+
+async function boot() {
+  refreshUI();
+  requestAnimationFrame(frame);
+  try {
+    R = await import(RAPIER_URL);
+    await R.init();
+  } catch (e) {
+    statusEl.textContent = 'The physics engine could not be loaded from the CDN. ' + (e && e.message ? e.message : '');
+    statusEl.classList.add('err');
+    return;
+  }
+  statusEl.classList.add('hide');
+  state.settings = { ...DEFAULTS };
+  startRun(state.settings);
+}
+boot();
+</script>
